<script setup lang="ts">
import { computed, ref } from 'vue'
import type { BuilderContext, BuilderDraft } from '../../lib/character-builder'
import { featOpportunities, selectedFeatIndexes, type AdvancementChoice } from '../../lib/advancements'
import { ABILITY_KEYS, type AbilityKey } from '../../lib/calc'
import { contentLabel, type HomebrewFeat } from '../../lib/srd'
const props=defineProps<{draft:BuilderDraft;context:BuilderContext;feats:HomebrewFeat[]}>()
const query=ref(''),selected=ref(''),target=ref(''),limit=ref(24)
const policy=computed(()=>featOpportunities(props.draft,props.context))
const catalog=computed(()=>props.feats.filter(f=>`${contentLabel(f)} ${f.description}`.toLowerCase().includes(query.value.toLowerCase())))
const detail=computed(()=>props.feats.find(f=>f.index===selected.value))
const selectedIndexes=computed(()=>selectedFeatIndexes(props.draft,props.context))
function choice(key:string):AdvancementChoice{return props.draft.advancements[key]??{kind:'later',feat:'',increases:{}}}
function setKind(key:string,kind:AdvancementChoice['kind']){props.draft.advancements[key]={kind,feat:'',increases:{}}}
function point(key:string,ability:AbilityKey,value:string){const current=choice(key);props.draft.advancements[key]={...current,increases:{...current.increases,[ability]:Number(value)}}}
function assign(){if(!detail.value||!target.value||selectedIndexes.value.includes(detail.value.index))return;props.draft.advancements[target.value]={kind:'feat',feat:detail.value.index,increases:{}};target.value=''}
function extra(){const key=`extra-${crypto.randomUUID()}`;props.draft.advancements[key]={kind:'feat',feat:'',increases:{}};target.value=key}
const featName=(index:string)=>{const feat=props.feats.find(f=>f.index===index);return feat?contentLabel(feat):index}
</script>
<template><div class="builder-advancements">
  <div class="cb-detail-panel"><div class="cb-detail-heading"><div><p class="cb-eyebrow">EARNED OPPORTUNITIES</p><h3>One choice. Two paths.</h3></div><span class="cb-count-pill">{{policy.slots.filter(s=>!s.key.startsWith('extra-')).length}} earned</span></div><p class="cb-reference-copy">At each class advancement, choose a feat or two ability points. Racial bonus opportunities grant feats. You can leave an opportunity for later.</p><p v-if="!policy.known" class="cb-field-hint">This class has no recognised advancement schedule. Use the table-rule override below for custom progression.</p><p v-if="!policy.slots.length" class="cb-empty">No feat or ability-increase opportunities at this level. Browse below, or enable the override for a table-granted feat.</p>
    <article v-for="slot in policy.slots" :key="slot.key" class="advancement-row"><div class="cb-detail-heading"><h4>{{slot.label}}</h4><span class="cb-badge">{{slot.racial?'FEAT':'FEAT OR +2 ABILITY POINTS'}}</span></div><label class="cb-field">Your choice<select :value="choice(slot.key).kind" @change="setKind(slot.key,($event.target as HTMLSelectElement).value as AdvancementChoice['kind'])"><option value="later">Choose later</option><option v-if="!slot.racial" value="asi">Ability score increase</option><option value="feat">Feat</option></select></label><p v-if="choice(slot.key).kind==='feat'" class="cb-reference-copy">{{choice(slot.key).feat?featName(choice(slot.key).feat):'Choose a feat in the browser below, then assign it to this opportunity.'}}</p>
      <div v-if="choice(slot.key).kind==='asi'" class="advancement-points"><label v-for="key in ABILITY_KEYS" :key="key" class="cb-field">{{key.toUpperCase()}}<input type="number" min="0" max="2" :value="choice(slot.key).increases[key]??0" :aria-label="`${slot.label} ${key.toUpperCase()} increase`" @input="point(slot.key,key,($event.target as HTMLInputElement).value)" /></label></div><p v-if="choice(slot.key).kind==='asi'" class="cb-field-hint">{{Object.values(choice(slot.key).increases).reduce((sum,v)=>sum+(v??0),0)}} / 2 ability points allocated. These are included in your final scores.</p>
      <details v-if="choice(slot.key).kind==='feat'&&choice(slot.key).feat" class="cb-advanced"><summary>Ability bonuses granted by this feat</summary><p class="cb-field-hint">If the feat increases an ability, record only that granted bonus here. Read its description for any choices. Other special effects are retained as feature text.</p><div class="advancement-points"><label v-for="key in ABILITY_KEYS" :key="key" class="cb-field">{{key.toUpperCase()}}<input type="number" min="0" max="2" :value="choice(slot.key).increases[key]??0" @input="point(slot.key,key,($event.target as HTMLInputElement).value)" /></label></div></details><button v-if="slot.key.startsWith('extra-')" type="button" class="cb-text-button" @click="delete draft.advancements[slot.key]">Remove extra opportunity</button>
    </article>
  </div>
  <div class="cb-subsection"><h3>Find a feat</h3><label class="cb-field">Search imported feats<input v-model="query" type="search" placeholder="Search names, effects, and source packs…" @input="limit=24" /></label><p class="cb-field-hint">{{catalog.length}} matching feats. Already selected feats are marked.</p><div class="advancement-browser"><button v-for="feat in catalog.slice(0,limit)" :key="feat.index" type="button" :class="{selected:selected===feat.index}" @click="selected=feat.index"><strong>{{contentLabel(feat)}}</strong><small>{{selectedIndexes.includes(feat.index)?'✓ Selected':feat.sourcePack}}</small></button></div><button v-if="catalog.length>limit" type="button" class="cb-text-button" @click="limit+=24">Show more feats</button><p v-if="!feats.length" class="cb-empty">No imported feats are available. Import an Orcbrew pack to add feat definitions.</p>
    <div v-if="detail" class="cb-detail-panel"><h3>{{contentLabel(detail)}}</h3><p class="cb-reference-copy">{{detail.description||'No description supplied by this source.'}}</p><p class="cb-field-hint">Check the feat’s prerequisites and choices with your table before assigning it.</p><div class="cb-inline-form"><label class="cb-field cb-grow">Use this opportunity<select v-model="target"><option value="">Choose an earned opportunity…</option><option v-for="slot in policy.slots" :key="slot.key" :value="slot.key">{{slot.label}}{{choice(slot.key).kind!=='later'?' · replaces current choice':''}}</option></select></label><button type="button" class="cb-button cb-button-primary" :disabled="!target||selectedIndexes.includes(detail.index)" @click="assign">{{selectedIndexes.includes(detail.index)?'Already selected':'Assign feat'}}</button></div></div>
  </div>
  <div class="cb-subsection"><label class="cb-checkbox-label"><input v-model="draft.featLimitOverride" type="checkbox" /> Override · allow extra feats / table rules</label><p class="cb-field-hint">Extra opportunities are active only while this override is enabled. Earned class choices still use one feat or two ability points.</p><button v-if="draft.featLimitOverride" type="button" class="cb-button cb-button-secondary" @click="extra">+ Extra feat opportunity</button><div v-if="draft.feats.length" style="margin-top:16px"><h4>Feats retained from an earlier draft</h4><p class="cb-field-hint">Reassign these through earned opportunities, or keep them with the override enabled.</p><div v-for="index in draft.feats" :key="index" class="cb-selected-row"><span>{{featName(index)}}</span><button type="button" @click="draft.feats=draft.feats.filter(f=>f!==index)">Remove</button></div></div><details class="cb-advanced"><summary>Racial bonus feat allowance</summary><p class="cb-field-hint">Detected allowance: {{policy.racial}}. Set a value only if your racial rules grant a different number.</p><label class="cb-field">Racial feat opportunities<input type="number" min="0" max="10" :value="draft.racialFeatCountOverride" placeholder="Automatic" @input="draft.racialFeatCountOverride=($event.target as HTMLInputElement).value===''?null:Number(($event.target as HTMLInputElement).value)" /></label></details></div>
</div></template>
<style scoped>.advancement-row{padding:20px 0;border-top:1px solid var(--cb-line);margin-top:20px}.advancement-row h4{font:19px Georgia,serif}.advancement-points{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:9px;margin-top:16px}.advancement-points input{text-align:center!important;padding:10px!important}.advancement-browser{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:16px;max-height:360px;overflow:auto;padding:3px}.advancement-browser button{text-align:left;background:var(--cb-soft);border:1px solid var(--cb-line);border-radius:6px;padding:13px;cursor:pointer}.advancement-browser button.selected{border-color:var(--cb-accent-mark);background:var(--cb-accent-soft)}.advancement-browser strong{font-size:13px;display:block;color:var(--cb-ink);font-weight:500}.advancement-browser small{font-size:10px;color:var(--cb-muted);display:block;margin-top:6px}.advancement-browser button:focus-visible{outline:2px solid var(--cb-accent-mark)}@media(max-width:600px){.advancement-points{grid-template-columns:repeat(3,minmax(0,1fr))}.advancement-browser{grid-template-columns:1fr}}</style>
